def typed(value,schema,path):
    if value is None:
        require(schema['nullable'],'Nonnullable typed inspector fact missing: '+path);return
    kind=schema['kind']
    if kind=='integer':require(type(value) is int and int(schema['minimum'])<=value<=int(schema['maximum']),'Typed integer/width mismatch: '+path)
    elif kind=='bool':require(type(value) is bool,'Typed boolean mismatch: '+path)
    elif kind=='number':require(type(value) in (int,float) and abs(value)<=(3.4028234663852886e38 if schema['clr']=='System.Single' else 1.7976931348623157e308) and math.isfinite(value),'Typed finite numeric mismatch: '+path)
    elif kind=='string':require(type(value) is str,'Typed string mismatch: '+path)
    elif kind=='enum':
        names={v['name'] for v in schema['values']}
        require(type(value) is str and (value in names or schema['flags'] and all(part.strip() in names for part in value.split(','))),'Unknown typed enum: '+path)
    elif kind=='object':
        require(type(value) is dict and set(value)==set(schema['properties']),'Missing/extra typed record fields: '+path)
        for key,child in schema['properties'].items():typed(value[key],child,path+'.'+key)
    else:require(False,'Unknown inspector schema kind')

def facts(value,timings):
    require(type(timings) is dict,'Timing facts unavailable')
    expected=set()
    def check(node,schema,path):
        if node is None:typed(node,schema,path);return
        if schema['kind']!='object':typed(node,schema,path);return
        properties=schema['properties'];state_keys={k for k in properties if not k.endswith('Milliseconds')}
        require(type(node) is dict and set(node)==state_keys,'Missing/extra typed state/activity fields: '+path)
        for key,child in properties.items():
            child_path=key if not path else path+'.'+key
            if key.endswith('Milliseconds'):
                expected.add(child_path);require(child_path in timings,'Required typed timing leaf missing: '+child_path);typed(timings[child_path],child,child_path)
            else:check(node[key],child,child_path)
    check(value,FACT_SCHEMA,'')
    require(set(timings)==expected,'Missing/extra timing paths for actual present typed records')

def read_inspector(directory,reference,stage_reference,stage,required_version=1):
    if reference is None:
        require(required_version is None,'Selected inspector-v1 requires its original record; no historical downgrade')
        return dict(available=False,reason='Historical stage evidence has no input inspector; not retroqualified')
    require(type(required_version) is int and required_version==1,'Unsupported selected inspector version')
    path=safe(directory,reference['path']);require(path.is_file() and not path.is_symlink() and path.stat().st_size<=8*1024*1024,'Missing/oversized inspector record')
    raw=path.read_bytes();require(sha256_bytes(raw)==digest(reference['sha256'],'inspector'),'Inspector file hash differs')
    r=parse_json_bytes(raw)
    require(type(r.get('schemaVersion')) is int and r['schemaVersion']==1 and r.get('kind')=='reference-world-input-inspector' and r.get('qualified') is False,'Wrong inspector contract')
    require(r.get('complete') is True and 'failure' in r and r['failure'] is None,'Incomplete inspector prefix remains unavailable; retain original producer failure')
    for key in ('producer','sourceSha','runtimeFingerprint','recipeFingerprint','recipeInputBytesBase64'):require(r.get(key)==stage[key],'Inspector source/runtime/recipe/producer differs from own stage')
    require(r.get('profileDomain')=='effective-quality-profile','Inspector profile domain is not the effective quality profile; ordinary-ready hashes full composition separately')
    profile_raw=base64.b64decode(r['profileInputBytesBase64'],validate=True);require(sha256_bytes(profile_raw)==digest(r['profileFingerprint'],'inspector profile') and same(parse_json_bytes(profile_raw),stage['effectiveProfile']),'Actual profile bytes/hash differ')
    integer(r.get('processId'),'inspector PID',1);integer(r.get('managedOwnerThread'),'managed owner',1);integer(r.get('nativeOwnerThread'),'native owner',1)
    require(r['processId']==stage['deviceIdentity']['processId'],'Inspector belongs to another producer PID')
    rep=integer(r.get('repetition'),'inspector repetition');repeats=integer(r.get('declaredRepeats'),'declared repeats',2)
    require(repeats<=128 and rep<repeats and rep==stage['repetition'] and integer(r.get('capacity'),'inspector storage',1)==5*repeats<=640,'Invalid declared inspector storage/repetition')
    target=r.get('stageDiagnostics');require(type(target) is dict and type(target.get('file')) is str and '/' not in target['file'],'Original same-directory stage reference missing')
    require(safe(path.parent,target['file'])==safe(directory,stage_reference['path']) and digest(target['sha256'],'inspector stage')==digest(stage_reference['sha256'],'original stage'),'Inspector stage hash/path differs')
    expected_capture={k:stage[k] for k in ('submission','completedFence','frameIndex','presentedBefore','presentedAfter','deviceIdentity')};expected_capture['bufferCount']=stage['outputRaster']['bufferCount']
    require(same(r.get('captured'),expected_capture),'Inspector actual slot/fence/submission/device/presentation tuple differs')
    sites=['HostReadbackPrepare'] if r['producer']=='actual-render-host' else ['NativeFixedPoseRestore','CaptureEnsurePrepared'] if rep==0 else ['CaptureEnsurePrepared']
    rows=r.get('observations');require(type(rows) is list and len(rows)==2*len(sites)+1,'Missing/extra inspector phases')
    base=rep*3 if r['producer']=='actual-render-host' else 0 if rep==0 else 5+(rep-1)*3
    previous=None;prior_tuple=None
    for i,row in enumerate(rows):
        require(type(row.get('index')) is int and row['index']==base+i and type(row.get('repetition')) is int and row['repetition']==rep,'Duplicate/reordered inspector observations')
        site_index=i//2;final=i==len(rows)-1
        require(type(row.get('siteOrdinal')) is int and row['siteOrdinal']==site_index and row.get('site')==(None if final else sites[site_index]) and row.get('phase')==('AfterCaptureAndClientRetire' if final else 'BeforeSite' if i%2==0 else 'AfterSite'),'Invalid inspector phase/site sequence')
        invoked=row.get('preparationInvoked')
        if final or i%2==0:require(invoked is None,'Before-site predicate is unknown; final phase has no invocation predicate')
        else:require(type(invoked) is bool and (sites[site_index]=='CaptureEnsurePrepared' or invoked),'Actual site invocation flag differs')
        begin=integer(row.get('readStartTick'),'observation read start');end=integer(row.get('readEndTick'),'observation read end',begin)
        require(previous is None or begin>=previous,'Inspector read brackets regress');previous=end
        require(row.get('managedOwnerThread')==r['managedOwnerThread'] and type(row.get('managedOwnerThread')) is int and row.get('nativeOwnerThread')==r['nativeOwnerThread'] and type(row.get('nativeOwnerThread')) is int,'Foreign inspector owner')
        require(same(row.get('camera'),stage['camera']),'Inspector actual camera differs from own stage')
        state=row.get('stateAndActivityFacts');facts(state,row.get('timingFacts'))
        surface=state['graphics']['surface'];raster=stage['outputRaster']
        require(surface['width']==raster['width'] and surface['height']==raster['height'] and surface['bufferCount']==raster['bufferCount'] and 0<=surface['frameIndex']<surface['bufferCount'],'Phase surface raster/buffer/slot differs from original stage')
        if state['deviceIdentity'] is not None:require(same(state['deviceIdentity'],stage['deviceIdentity']),'Foreign pre/after-phase device identity')
        current=state['lastSubmission']
        if current is not None:
            require(current['generation']==stage['submission']['generation'] and 0<current['resourceGeneration']<=stage['submission']['resourceGeneration'],'Phase device/resource generation differs')
            require((current['submission']==0 and current['submittedFence']==0) or current['submission']>0 and current['submittedFence']>0,'Phase prior submission availability is incoherent')
            require(current['submission']<=stage['submission']['submission'] and current['submittedFence']<=stage['submission']['submittedFence'],'Phase submitted state is from the future')
            if not final:require(current['submission']<stage['submission']['submission'] and current['submittedFence']<stage['submission']['submittedFence'],'Pre-capture submitted state is not a prior frame')
            if prior_tuple is not None:require(current['submission']>=prior_tuple['submission'] and current['resourceGeneration']>=prior_tuple['resourceGeneration'] and current['submittedFence']>=prior_tuple['submittedFence'] and (current['submission']!=prior_tuple['submission'] or current['submittedFence']==prior_tuple['submittedFence']),'Phase prior submission progression regressed or changed fence without a new frame')
            prior_tuple=current
    require(rows[-2]['stateAndActivityFacts']['graphics']['surface']['frameIndex']==stage['frameIndex'] and type(rows[-2]['stateAndActivityFacts']['graphics']['surface']['frameIndex']) is int,'Captured slot differs from actual pre-capture surface; post-capture surface is next slot')
    last_pre=rows[-2]['stateAndActivityFacts']['lastSubmission']
    if last_pre is not None:require(last_pre['submission']+1==stage['submission']['submission'] and last_pre['submittedFence']<stage['submission']['submittedFence'],'Last pre-capture submitted state is not the actual immediate predecessor')
    after=rows[-1]['stateAndActivityFacts']
    require(same(after['lastSubmission'],stage['submission']) and same(after['deviceIdentity'],stage['deviceIdentity']) and after['inputFingerprint']==stage['inputFingerprint'] and integer(after['graphics']['surface']['bufferCount'],'after-capture buffer count',1)==stage['outputRaster']['bufferCount'] and integer(after['graphics']['surface']['presentedFrameCount'],'after-capture present count',1)==stage['presentedAfter'],'After-capture public submission/surface facts differ')
    return dict(available=True,preCaptureSubmissionAvailable=last_pre is not None,record=r,sha256=sha256_bytes(raw),readStartTick=rows[0]['readStartTick'],readEndTick=rows[-1]['readEndTick'])

def changes(before,after,prefix=''):
    if same(before,after):return []
    if type(before) is dict and type(after) is dict:
        result=[]
        for key in sorted(set(before)|set(after)):
            path=key if not prefix else prefix+'.'+key
            if key not in before or key not in after:result.append(dict(path=path,presentBefore=key in before,presentAfter=key in after,before=before.get(key),after=after.get(key)))
            else:result.extend(changes(before[key],after[key],path))
        return result
    return [dict(path=prefix,before=before,after=after)]

def validate_loaded(directory,stage_references,captures,inspector_references,required_version=1):
    if inspector_references is None:
        require(required_version is None,'Selected inspector-v1 requires every declared record')
        return dict(schemaVersion=1,available=False,status='historical-unavailable',qualified=False)
    require(type(required_version) is int and required_version==1 and type(inspector_references) is list and len(inspector_references)==len(stage_references)==8,'All eight selected inspector records required')
    require(len({safe(directory,r['path']) for r in inspector_references})==8,'Inspector refs cannot alias/repeat')
    loaded=[read_inspector(directory,r,s,c[0],required_version) for r,s,c in zip(inspector_references,stage_references,captures)]
    first=loaded[0]['record']
    for i,item in enumerate(loaded):
        r=item['record'];require(r['declaredRepeats']==8 and r['repetition']==i,'Declared fixed repetition series differs')
        require(all(same(r[k],first[k]) for k in ('sourceSha','producer','runtimeFingerprint','recipeFingerprint','profileFingerprint','profileInputBytesBase64','processId','managedOwnerThread','nativeOwnerThread')),'Inspector immutable identity changed within lane')
        require(i==0 or loaded[i-1]['readEndTick']<=item['readStartTick'],'Inspector chronology regressed between repeats')
        if i:
            current=captures[i][0];previous=captures[i-1][0]
            for observation in r['observations'][:-1]:
                prior=observation['stateAndActivityFacts']['lastSubmission']
                if prior is not None:require(same(prior,previous['submission']),'A later fixed repetition must begin from its own previous captured submission; no intervening frame is declared')
            require(current['submission']['submission']==previous['submission']['submission']+1 and current['submission']['submittedFence']>previous['submission']['submittedFence'] and current['submission']['resourceGeneration']==previous['submission']['resourceGeneration'] and same(current['deviceIdentity'],previous['deviceIdentity']) and current['presentedBefore']==previous['presentedAfter'],'Inspector own-stage submission/device chronology differs')
    return dict(schemaVersion=1,available=True,status='complete-observed-aggregates',qualified=False,records=[dict(sha256=x['sha256'],repetition=x['record']['repetition'],preparationChanges=[dict(site=x['record']['observations'][j]['site'],invoked=x['record']['observations'][j+1]['preparationInvoked'],stateAndActivityChanges=changes(x['record']['observations'][j]['stateAndActivityFacts'],x['record']['observations'][j+1]['stateAndActivityFacts']),timingChanges=changes(x['record']['observations'][j]['timingFacts'],x['record']['observations'][j+1]['timingFacts'])) for j in range(0,len(x['record']['observations'])-1,2)],afterCaptureChangesFromFirst=changes(first['observations'][-1]['stateAndActivityFacts'],x['record']['observations'][-1]['stateAndActivityFacts'])) for x in loaded],scope='Own-lane source/stage/slot/submission joins only; equal aggregates do not prove equal GPU bindings/content or a pixel cause')

def validate_series(directory,stage_references,inspector_references,required_version=1):
    from stage_diagnostics import read_capture
    captures=[read_capture(directory,r) for r in stage_references]
    return validate_loaded(directory,stage_references,captures,inspector_references,required_version)


def compare_inspector_lanes(directory,native_stage_refs,native_inspector_refs,host_stage_refs,host_inspector_refs):
    from stage_diagnostics import read_capture
    lanes=[]
    for stages,inspectors in ((native_stage_refs,native_inspector_refs),(host_stage_refs,host_inspector_refs)):
        captures=[read_capture(directory,r) for r in stages];validation=validate_loaded(directory,stages,captures,inspectors,1)
        rows=[read_inspector(directory,r,s,c[0],1)['record'] for r,s,c in zip(inspectors,stages,captures)]
        lanes.append((validation,rows))
    native,host=lanes[0][1],lanes[1][1]
    for a,b in zip(native,host):
        require(a['producer']=='native-reference' and b['producer']=='actual-render-host','Wrong cross-lane producer roles')
        require(all(a[k]==b[k] for k in ('sourceSha','runtimeFingerprint','recipeFingerprint')) and same(parse_json_bytes(base64.b64decode(a['profileInputBytesBase64'],validate=True)),parse_json_bytes(base64.b64decode(b['profileInputBytesBase64'],validate=True))) and same(a['observations'][-1]['camera'],b['observations'][-1]['camera']),'Cross-lane immutable source/runtime/recipe/quality-profile/pose differs')
    return dict(schemaVersion=1,kind='cross-lane-world-input-observations',qualified=False,native=lanes[0][0],host=lanes[1][0],
        repetitions=[dict(repetition=i,stateAndActivityChanges=changes(a['observations'][-1]['stateAndActivityFacts'],b['observations'][-1]['stateAndActivityFacts'])) for i,(a,b) in enumerate(zip(native,host))],
        scope='Independent PID/device-session/generation/fence values are deliberately not equalized. Physical UUID/PCI and pixels remain the separate strict stage comparator responsibility; changed/equal aggregates do not establish cause.')
